mapper.update:
UPDATE tb_comment
SET reply_total = reply_total + #{delta}
WHERE id = #{id} AND level = 1 AND deleted = 0

mapper.select:
SELECT DISTINCT ON (parent_id) id, post_id, user_id, content_uuid, is_content_empty, image_url, level, reply_total, like_total, parent_id, reply_comment_id, reply_user_id, is_top, deleted, create_time, update_time FROM tb_comment WHERE deleted = 0 AND level = 2 AND parent_id IN
#{parentId}
ORDER BY parent_id, create_time ASC, id ASC

mapper.update:
UPDATE tb_comment
SET deleted = 1, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.select:
SELECT id, post_id, parent_id, level, content_uuid, create_time
FROM tb_comment
WHERE parent_id = #{rootId}
  AND level = 2
  AND deleted = 0
  AND id > #{lastId}
ORDER BY id ASC
LIMIT #{limit}

UPDATE tb_comment SET deleted = 1, update_time = CURRENT_TIMESTAMP WHERE deleted = 0 AND id IN
#{id}
RETURNING id
